package bw.ac.banking.service;
import bw.ac.banking.dao.*;import bw.ac.banking.model.*;import java.sql.*;import java.security.*;import java.security.spec.*;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;import java.util.*;
public final class AuthService {
 private final Database db;private final CustomerDAO customers=new CustomerDAO();private final SecureRandom random=new SecureRandom();
 public AuthService(Database db){this.db=db;}
 private static String hash(char[] password,byte[] salt){try{PBEKeySpec spec=new PBEKeySpec(password,salt,120000,256);byte[] data=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return Base64.getEncoder().encodeToString(data);}catch(Exception e){throw new IllegalStateException(e);}}
 public long register(String username,char[] password,String first,String last,String address,boolean employed,String employer,String employerAddress)throws SQLException{if(username==null||username.isBlank()||password.length<8)throw new IllegalArgumentException("Username and password (8+ characters) required");byte[] salt=new byte[16];random.nextBytes(salt);String digest=hash(password,salt);try(Connection c=db.connect()){c.setAutoCommit(false);try{long id=customers.create(c,new Customer(0,first,last,address,employed,employer,employerAddress));try(PreparedStatement p=c.prepareStatement("INSERT INTO users(customer_id,username,salt,password_hash) VALUES(?,?,?,?)")){p.setLong(1,id);p.setString(2,username);p.setString(3,Base64.getEncoder().encodeToString(salt));p.setString(4,digest);p.executeUpdate();}c.commit();return id;}catch(Exception e){c.rollback();throw e;}}}
 public Customer login(String username,char[] password)throws SQLException{try(Connection c=db.connect();PreparedStatement p=c.prepareStatement("SELECT customer_id,salt,password_hash FROM users WHERE username=?")){p.setString(1,username);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Invalid credentials");byte[] salt=Base64.getDecoder().decode(r.getString("salt"));byte[] expected=Base64.getDecoder().decode(r.getString("password_hash"));byte[] actual=Base64.getDecoder().decode(hash(password,salt));if(!MessageDigest.isEqual(expected,actual))throw new IllegalArgumentException("Invalid credentials");return customers.get(c,r.getLong("customer_id"));}}}
}
